texte = {
  "one": "Du hast {n} neue Nachricht.",
  "other": "Du hast {n} neue Nachrichten.",
}

def nachricht(n):
    form = "one" if n == 1 else "other"
    return texte[form].format(n=n)

for n in (0, 1, 5):
    print(nachricht(n))
# Du hast 0 neue Nachrichten.
# Du hast 1 neue Nachricht.
# Du hast 5 neue Nachrichten.

